// The set's definition, or nullptr for an unknown (set, version) pair.
constexpr const JointSetInfo* find(JointSet set, std::uint16_t version) noexcept
{
    for (const JointSetInfo& info : kJointSets) {
        if (info.id == set && info.version == version) {
            return &info;
        }
    }
    return nullptr;
}

